pub fn dumpRecordType<'a>(mut in_txt: Tpl::Text, mut in_a_ty: &'a metamodelica::Ref<DAE::Type>) -> Result<Tpl::Text> {
    '__tco: loop {
        break ::match_deref::match_deref! { match in_a_ty {
            Deref @ DAE::Type::T_COMPLEX { complexClassType: i_complexClassType, varLst: i_varLst, .. } => {
                let mut txt = in_txt;
                let mut ret_1;
                let mut l_name;
                let mut l_vars;
                ret_1 = ClassInfUtil::getStateName(i_complexClassType);
                l_name = AbsynDumpTpl::dumpPath((*Tpl::emptyTxt).clone(), &ret_1)?;
                l_vars = dumpRecordVars((*Tpl::emptyTxt).clone(), i_varLst)?;
                txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("record ") }))?;
                txt = Tpl::writeText(txt, l_name.clone())?;
                txt = Tpl::softNewLine(txt)?;
                txt = Tpl::pushBlock(txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
                txt = Tpl::writeText(txt, l_vars)?;
                txt = Tpl::softNewLine(txt)?;
                txt = Tpl::popBlock(txt)?;
                txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("end ") }))?;
                txt = Tpl::writeText(txt, l_name)?;
                txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(";") }))?;
                Ok(txt)
            }
            Deref @ DAE::Type::T_FUNCTION { funcResultType: i_funcResultType, .. } => {
                let mut txt = in_txt;
                (in_txt, in_a_ty) = (txt, i_funcResultType);
                continue '__tco;
            }
            _ => {
                let mut txt = in_txt;
                Ok(txt)
            }
            _ => Err("dumpRecordType: no case matched"),
        } };
    }
}

